xml.Script:
        Colors[0] := 'DD0000'; // Red
        Colors[1] := 'FF800A'; // Orange
        Colors[2] := '009900'; // Green
        Colors[3] := '0000DD'; // Blue
        Colors[4] := '800080'; // Violett
        Colors[5] := 'FFFF00'; // Yellow
        Colors[6] := 'FFFFFF'; // White

        R := 0.6;
        H := 0.5;
        sAngle := 2*Pi/5;

        for i := 0 to 4 do begin
            ax[i] := R * cos(2*Pi/5 * i);
            ay[i] := R * sin(2*Pi/5 * i);
        end;

        D := R * cos(2*Pi/5);

        N := 60;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
